async function complete(env:Cloudflare.Env,owner:string,id:string,hash:string,result:unknown){await env.DB!.prepare('UPDATE v2_recovery_operations SET result=? WHERE owner=? AND id=? AND hash=?').bind(JSON.stringify(result),owner,id,hash).run();}
